package com.atlasiq.governance;
import com.atlasiq.qir.*;import jakarta.enterprise.context.ApplicationScoped;import java.util.*;
@ApplicationScoped public class ArchitectureFitnessService {private final ArchitectureGovernanceEngine engine;public ArchitectureFitnessService(ArchitectureGovernanceEngine e){engine=e;}public Fitness evaluate(QirModel m,PolicyPack p){var violations=engine.evaluate(m,p);long critical=violations.stream().filter(v->"critical".equalsIgnoreCase(v.severity())||"high".equalsIgnoreCase(v.severity())).count();int score=Math.max(0,100-(int)Math.min(100,critical*20L+(violations.size()-critical)*5L));return new Fitness(score,score>=90?"healthy":score>=70?"warning":"failing",violations);}public record Fitness(int score,String status,List<PolicyViolation> violations){}}